'use strict';
require(["jquery", "xwiki-meta"], function ($, xm) {
  var uidManager = XWiki.Model.resolve('SecurityAdvisoryApplication.Code.AdvisoryUIDManager', XWiki.EntityType.DOCUMENT);

  var redirectToPage = function () {
    var queryString = "action=getuid&form_token=" + xm.form_token;
    var url = new XWiki.Document(uidManager).getURL('view', queryString);
    window.location.href=url;
  };

  var initialize = function () {
    $('a.action.add').on('click', function() {
      redirectToPage();
    });
  };

  initialize() && document.observe("xwiki:dom:loaded", initialize);
});
